.workflow-heading { display: grid; grid-template-columns: minmax(0, 1fr) minmax(16rem, 2fr); gap: 20px; align-items: end; padding-bottom: 24px; border-bottom: 1px solid var(--divider); }
.workflow-heading :is(h1, h2), .workflow-heading p { margin: 0; }
